with parsed as (select id, service, latency_ms, status_code, payload_json, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count, coalesce(context['region'], 'none') as region_or_default from app_logs) select service, case when retry_count >= 4 then 'HIGH' else 'LOW' end as retry_count_tier, corr(status_code, latency_ms) as corr_status_code_latency_ms, approx_percentile(latency_ms, array(0.25, 0.5, 0.75)) as latency_ms_quartiles, count(*) filter (where service = 'billing') as billing_rows from parsed group by service, case when retry_count >= 4 then 'HIGH' else 'LOW' end;
